-- Cadencia Rezagados: diseño «lienzo» + portada con foto en las 31 plantillas.
-- La portada va como primer bloque; en las dos plantillas cuya foto de cuerpo
-- estaba pegada al saludo (L1, L6) esa foto baja hasta antes del aviso.
-- El compilador aprende el bloque 'portada' y el layout 'lienzo' en el mismo commit.
begin;
-- El check de `layout` traía nombres de diseños que nunca existieron en el
-- compilador (newsletter, promocional…). Se conservan para no romper filas y
-- se agrega el único que hoy significa algo además de simple: lienzo.
alter table email_templates drop constraint if exists email_templates_layout_check;
alter table email_templates add constraint email_templates_layout_check
  check (layout = any (array['simple','lienzo','newsletter','promocional','bienvenida','seguimiento','custom']));
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/probador.jpg", "alt": "", "etiqueta": "Para empezar", "titulo": "Esto es lo que hace Sacs hoy"}, {"id": "t1", "tipo": "texto", "texto": "Hola {{nombre|Hola}}, te escribe Andrea, de Sacs.\n\nHace un tiempo miraste nuestro sistema y no llegamos a sentarnos. Antes de mandarte nada más, déjame decirte en dos minutos qué hacemos hoy — porque el sistema de hace un año no se parece al de ahora."}, {"id": "t2", "tipo": "texto", "texto": "Sacs es el sistema con el que operan marcas de ropa, calzado y accesorios en México. No es un punto de venta con un módulo de moda encima: está hecho para un negocio donde una prenda no es «una prenda», son tallas, colores y temporadas."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que resuelve, en corto"}, {"id": "l1", "tipo": "lista", "items": ["Tu inventario por talla y color, en matriz — ves de un golpe qué talla y qué color te queda en cada tienda, sin abrir tres archivos", "Qué hay en la otra sucursal, al momento — y el traspaso que completa la corrida rota, sin llamar por teléfono", "Qué resurtir y qué ya no comprar — rotación por modelo, talla y tienda, y aviso de la prenda que lleva semanas colgada", "De la foto a la venta, con IA — subes la foto de la prenda y sale puesta en un modelo, con su ficha y su video para redes, sin sesión de fotos", "Probador virtual — tu clienta ve cómo se le vería a ella, con lo que sí hay en su talla", "Punto de venta que no se cae sin internet, con apartados, abonos y cambios de talla", "Tu tienda en línea, Instagram, WhatsApp, Mercado Libre y TikTok Shop con el MISMO inventario del piso", "Tus clientas: qué se llevaron, puntos y monedero, y el aviso de colección nueva a quien ya te compró"]}, {"id": "a1", "tipo": "aviso", "texto": "La migración la hacemos nosotros: tus productos, tus clientas y tu historial. Tú no vacías nada a mano."}, {"id": "h2", "tipo": "encabezado", "nivel": 2, "texto": "Y si quieres verlo con lo tuyo"}, {"id": "t3", "tipo": "texto", "texto": "No es una demo de pantallas. Es una sesión consultiva de veinte minutos donde cargamos algunas de TUS prendas con sus tallas y colores, y sales viendo tu propia operación corriendo. Si al final te digo que todavía no te conviene, te lo digo igual."}, {"id": "bt", "sub": "20 minutos · sin costo · con tus propios productos", "href": "https://www.sacscloud.com/agendar/demo?utm_source=cadencia_rezagados&utm_medium=email&utm_campaign=rezagados&utm_content=presentacion", "tipo": "boton", "align": "center", "texto": "Agendar mi sesión consultiva →"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si hoy llevas el inventario en Excel o en una libreta, no llegas tarde: es justo donde el cambio se nota en la primera semana."}]'::jsonb where nombre='Rezagados 0 · Qué hace Sacs hoy' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-planta.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 1 de 10", "titulo": "La curva no es nacional"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, un lunes de estos vale la pena pensar en algo que casi nadie revisa. 🧠"}, {"id": "s0", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "La trampa de la segunda tienda"}, {"id": "t2", "tipo": "texto", "texto": "Una marca con una tienda tiene **una** curva de tallas: lo que se vende ahí es lo que hay que comprar."}, {"id": "t3", "tipo": "texto", "texto": "Con cuatro tiendas la mayoría sigue comprando igual — con una sola curva, la nacional, el promedio de todas."}, {"id": "t4", "tipo": "texto", "texto": "Y ahí está el problema: **el promedio no existe en ninguna tienda.**"}, {"id": "t5", "tipo": "texto", "texto": "La curva de una plaza de zona corporativa no se parece a la de una turística. Ni la de un centro histórico a la de un mall de suburbio. Cambia la talla que manda, cambia el color que sale primero, cambia hasta la semana en que se agota."}, {"id": "i1", "alt": "Interior de una tienda insignia de moda de dos niveles con escalera escultórica", "pie": "Cuando creces, no operas más grande. Operas distinto.", "src": "https://www.sacscloud.com/email/rezagados/rez-lunes.jpg", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "Comprar con la curva nacional te deja siempre en el mismo lugar: **sobra en todas y falta en todas, al mismo tiempo.** Y como el total cuadra, en el reporte se ve sano."}, {"id": "s1", "tipo": "separador"}, {"id": "h2", "tipo": "encabezado", "nivel": 2, "texto": "Cómo se ve cuando alguien sí lo mira"}, {"id": "t6", "tipo": "texto", "texto": "Las marcas que crecen bien hacen dos cosas distintas:"}, {"id": "l1", "tipo": "lista", "items": ["📐 **Compran por curva de tienda**, no por curva de marca. Aunque sea una sola orden al proveedor, el reparto se decide por destino.", "🔁 **Nivelan antes de recomprar.** Primero acomodan lo que ya pagaron entre sus tiendas; lo que falte después, eso sí se compra."]}, {"id": "t7", "tipo": "texto", "texto": "No es más trabajo. Es el mismo trabajo con la información partida por donde de verdad se parte."}, {"id": "s2", "tipo": "separador"}, {"id": "t8", "tipo": "texto", "texto": "Si quieres platicarlo sobre tus tiendas —no en abstracto— agenda media hora conmigo. Sin costo y sin demo: nada más ver tu caso."}, {"id": "b1", "sub": "30 minutos · sin costo · sobre tu operación, no sobre el sistema", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Una forma rápida de saber si te está pasando: mira tus dos tiendas que más venden y compara qué talla se agotó primero en cada una. Si es distinta, ya tienes dos curvas."}]'::jsonb where nombre='Rezagados L1 · La curva no es nacional' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-vitrina.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 10 de 10", "titulo": "El costo del metro cuadrado"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy la cuenta que casi nadie hace y que ordena todas las demás. 📐"}, {"id": "t2", "tipo": "texto", "texto": "En un centro comercial AAA de México, el costo de ocupación de los inquilinos ronda el **10.7% de sus ventas** — renta fija, renta variable y mantenimiento."}, {"id": "t3", "tipo": "texto", "texto": "Dale la vuelta a esa cifra y aparece una vara: **cuánto tiene que vender cada metro cuadrado tuyo para que el local se pague.**"}, {"id": "t4", "tipo": "texto", "texto": "Con una renta de $700 por metro al mes y un costo de ocupación sano del 12%, cada metro debe vender alrededor de **$70,000 al año**."}, {"id": "a1", "tipo": "aviso", "texto": "Ahora la parte útil: no todos tus metros venden igual. La mesa de entrada y la vitrina venden múltiplos de lo que vende el rincón del fondo. Pero **todos cuestan lo mismo por metro** — y casi siempre es el rincón el que tiene la mercancía que menos rota."}, {"id": "i1", "alt": "Visual merchandiser trabajando el aparador al anochecer", "pie": "El metro más caro de tu tienda es el que se ve desde la calle.", "src": "https://www.sacscloud.com/email/rezagados/rez-vitrina-noche.jpg", "tipo": "imagen"}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "El ejercicio que sale de ahí"}, {"id": "l1", "tipo": "lista", "items": ["📍 **Divide tu piso en tres zonas**: entrada, centro, fondo.", "💰 **Estima qué porcentaje de tu venta sale de cada una.**", "📦 **Mira qué mercancía ocupa el fondo.** Si es la de menor rotación, estás pagando renta AAA por guardar."]}, {"id": "t5", "tipo": "texto", "texto": "Un cambio de zona no cuesta nada y se nota en dos semanas."}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Un local chico de 21 a 60 m² en la Ciudad de México paga alrededor de 45% más por metro que un ancla. Si eres pequeño, cada metro te pesa más."}]'::jsonb where nombre='Rezagados L10 · El costo del metro cuadrado' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/rack-color.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 2 de 10", "titulo": "El denominador"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy una cuenta de una sola línea que cambia todas las demás. 🧮"}, {"id": "t2", "tipo": "texto", "texto": "El **sell-through** es la métrica que manda en moda: qué porcentaje de lo que trajiste ya se vendió."}, {"id": "t3", "tipo": "texto", "texto": "Y casi todo el mundo la calcula mal."}, {"id": "i1", "alt": "Comparación de las dos formas de calcular el sell-through", "pie": "El mismo estilo. Dos denominadores. Dos decisiones opuestas.", "src": "https://www.sacscloud.com/email/rezagados/rez-g-sellthrough.png", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "Si divides lo vendido entre **lo que te queda hoy**, te va a dar altísimo — y mientras más vendas, más alto. Es una métrica que se felicita sola."}, {"id": "t5", "tipo": "texto", "texto": "La buena divide entre **lo que recibiste**. Ese número te dice si la compra estuvo bien hecha, que es la única pregunta que importa."}, {"id": "a1", "tipo": "aviso", "texto": "La referencia del ramo: **arriba de 70% al año es sano**. Debajo de 50% antes de rebajas, hay que intervenir ya. Con el denominador equivocado nunca vas a saber en cuál de los dos estás."}, {"id": "s1", "tipo": "separador"}, {"id": "t6", "tipo": "texto", "texto": "Si quieres que lo veamos con tus estilos de la temporada pasada, agenda media hora. Sacamos el número bien calculado y de ahí sale la conversación sola."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Pruébalo hoy con un estilo que sientas exitoso. Si el número cae mucho al cambiar el denominador, es que compraste de más — no que vendiste poco."}]'::jsonb where nombre='Rezagados L2 · El denominador' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/cedis.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 3 de 10", "titulo": "Semanas de cobertura"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hay una métrica que casi no se usa en moda mexicana y que resuelve dos decisiones a la vez. ⏳"}, {"id": "t2", "tipo": "texto", "texto": "Se llama **semanas de cobertura**: cuántas semanas te dura lo que tienes al ritmo al que se está vendiendo."}, {"id": "t3", "tipo": "texto", "texto": "La cuenta es tonta de simple: existencia ÷ venta semanal."}, {"id": "i1", "alt": "Tres estilos con distintas semanas de cobertura", "pie": "El mismo inventario. Tres historias completamente distintas.", "src": "https://www.sacscloud.com/email/rezagados/rez-g-cobertura.png", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "Y lo que la hace útil es que **las dos decisiones caen del mismo número**:"}, {"id": "l1", "tipo": "lista", "items": ["🔴 **Menos de 4 semanas** — se te va a acabar antes de que llegue la reposición. Es lo que hay que pedir ya.", "🟢 **Entre 8 y 16** — sano. Ni te sobra ni te falta.", "🟠 **Más de 20** — capital dormido. Ese es el que hay que empezar a mover, no el que menos te gusta."]}, {"id": "a1", "tipo": "aviso", "texto": "El cambio de mentalidad: dejas de decidir por lo que te gusta o por lo que te sobra a la vista, y empiezas a decidir por **cuánto tiempo te dura**. Es la misma información que ya tienes, leída al derecho."}, {"id": "s1", "tipo": "separador"}, {"id": "t5", "tipo": "texto", "texto": "¿Lo sacamos con tus estilos? En media hora salen los tres grupos y sabes exactamente qué pedir y qué mover."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tienes varias tiendas, hazlo por tienda. El mismo estilo puede estar en rojo en una y en naranja en otra — y ahí no se compra: se traspasa."}]'::jsonb where nombre='Rezagados L3 · Semanas de cobertura' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/rebajas.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 4 de 10", "titulo": "Rebajar tarde"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, una de las decisiones más caras del año se toma por no tomarla. 📉"}, {"id": "t2", "tipo": "texto", "texto": "Rebajar duele. Se siente como aceptar que te equivocaste en la compra, así que se pospone: *«a ver si sale la semana que entra»*."}, {"id": "t3", "tipo": "texto", "texto": "Pero el mercado no espera."}, {"id": "i1", "alt": "Escalera de precios: de precio lleno a saldo", "pie": "Cinco escalones. Cada semana de indecisión te baja uno.", "src": "https://www.sacscloud.com/email/rezagados/rez-g-rebajas.png", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "La prenda que hoy sale con 20% de descuento, en cuatro semanas ya solo sale con 40%. Y en ocho, es saldo."}, {"id": "t5", "tipo": "texto", "texto": "**No perdiste margen al rebajar. Lo perdiste al esperar.**"}, {"id": "a1", "tipo": "aviso", "texto": "Lo que hacen las marcas que manejan bien esto: no rebajan por calendario ni por corazonada, sino por **cobertura**. Si un estilo trae más de 20 semanas a mitad de temporada, se marca — aunque duela, aunque haya gustado."}, {"id": "s1", "tipo": "separador"}, {"id": "t6", "tipo": "texto", "texto": "Si quieres armar tu regla de rebaja —cuándo, cuánto y sobre qué— agenda media hora y la dejamos escrita."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. La prueba de que esperar sale caro: mira una prenda que hoy esté en remate y calcula cuánto habrías ganado vendiéndola con 20% hace dos meses. Casi siempre es más que el total que dejará ahora."}]'::jsonb where nombre='Rezagados L4 · Rebajar tarde' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/etiqueta.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 5 de 10", "titulo": "Margen sobre costo"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy la confusión más cara del sector, y la más fácil de arreglar. 💰"}, {"id": "t2", "tipo": "texto", "texto": "Compras una prenda en $500 y la vendes en $1,000."}, {"id": "t3", "tipo": "texto", "texto": "¿Cuánto ganaste?"}, {"id": "i1", "alt": "Comparación entre margen sobre costo y margen sobre venta", "pie": "La misma operación. Dos números que no significan lo mismo.", "src": "https://www.sacscloud.com/email/rezagados/rez-g-margen.png", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "La mayoría dice **100%**, porque duplicaste el costo. Y es cierto que el markup es del 100%."}, {"id": "t5", "tipo": "texto", "texto": "Pero tu **margen** es 50%: de cada peso que entra a la caja, cincuenta centavos son tuyos y cincuenta ya eran del proveedor."}, {"id": "a1", "tipo": "aviso", "texto": "¿Por qué importa? Porque la renta, la nómina y la luz se pagan con el margen, no con el markup. Si presupuestas tu año pensando que ganas el 100%, **te va a faltar exactamente la mitad** — y no vas a entender por qué."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "La regla de bolsillo"}, {"id": "t6", "tipo": "texto", "texto": "Markup del 100% → margen del 50%. Markup del 150% → margen del 60%. Markup del 233% → margen del 70%."}, {"id": "t7", "tipo": "texto", "texto": "Si alguien te dice que trabaja «al 200 de margen», casi siempre quiere decir markup. Vale la pena preguntar."}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "¿Dudas con tus números? Mándanos un mensaje", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20revisar%20como%20estoy%20calculando%20mi%20margen", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Este error se multiplica por cada estilo y por cada temporada. Es de las pocas cosas que se arreglan en una tarde y se notan todo el año."}]'::jsonb where nombre='Rezagados L5 · Margen sobre costo' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/caja.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 6 de 10", "titulo": "El 35% que se devuelve"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, si vendes en línea, este es el número que casi nadie te dice. 📦"}, {"id": "t2", "tipo": "texto", "texto": "**El 35% de lo que se vende de moda en línea en México se devuelve.** Es la tasa más alta de todas las categorías — muy por encima de electrónicos, que anda en 12%."}, {"id": "t3", "tipo": "texto", "texto": "Y la causa número uno no es el color, ni el envío, ni que no gustó."}, {"id": "t4", "tipo": "texto", "texto": "**Es la talla.** Un tercio de todas las devoluciones."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Por qué pasa, de verdad"}, {"id": "l1", "tipo": "lista", "items": ["📏 **Cada marca talla distinto** y el cliente lo sabe. Ante la duda, pide dos y regresa una — eso ya está contemplado en su compra.", "🇲🇽 **La tabla equivocada.** En México los jeans se venden en nones —3, 5, 7, 9— y muchas tiendas en línea muestran la tabla estadounidense en pares.", "🕳️ **La talla que no estaba.** Compra la que sí había, no la suya."]}, {"id": "i1", "alt": "Diez prendas, tres y media devueltas", "pie": "Moda es la categoría con más devoluciones de México.", "src": "https://www.sacscloud.com/email/rezagados/rez-g-devoluciones.png", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "Lo que separa a las marcas que lo resuelven: dejan de pelear contra la devolución y montan **cambio** en su lugar. La pieza no se pierde, la venta no se cae, y el cliente vuelve. Pero para eso hay que saber qué talla hay y en qué tienda — que es justo lo que casi nadie tiene a la mano."}, {"id": "s2", "tipo": "separador"}, {"id": "t5", "tipo": "texto", "texto": "Si quieres ver cuánto te está costando y qué se puede hacer, agenda media hora."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Un ejercicio incómodo: cuenta cuántas devoluciones tuviste el mes pasado y multiplica por el costo del envío ida y vuelta. Ese número no aparece en ningún reporte de ventas."}]'::jsonb where nombre='Rezagados L6 · El 35% que se devuelve' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/hoja-linea.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 7 de 10", "titulo": "Comprar a ciegas"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy el problema estructural del calendario de la moda. 📅"}, {"id": "t2", "tipo": "texto", "texto": "Intermoda de julio es donde se compra el Otoño-Invierno. Cuatro días en Expo Guadalajara."}, {"id": "t3", "tipo": "texto", "texto": "Y en julio, tu Primavera-Verano **todavía no cierra**."}, {"id": "i1", "alt": "Compradores recorriendo los stands de una feria de moda", "pie": "Cuatro días para comprometer seis meses de capital.", "src": "https://www.sacscloud.com/email/rezagados/rez-feria.jpg", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "Así que compras la siguiente temporada con lo que **recuerdas** de la que está corriendo: los estilos que se te vienen a la cabeza, los que te comentó una encargada, los que viste apilados el último sábado."}, {"id": "a1", "tipo": "aviso", "texto": "El sesgo es predecible: te acuerdas de lo que se agotó rápido —porque duele— y de lo que sobra a la vista. **Se te olvida lo que se vendió constante y sin ruido**, que suele ser tu verdadero negocio."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que sí se puede llevar a la feria"}, {"id": "l1", "tipo": "lista", "items": ["📊 **Sell-through parcial por estilo**, aunque la temporada no haya cerrado. A mitad de camino ya se sabe quién va bien.", "📐 **La curva real por tienda**, no la nacional.", "🕳️ **Los huecos**: qué tallas se agotaron pronto y en cuáles nunca hubo."]}, {"id": "t5", "tipo": "texto", "texto": "Con esas tres hojas impresas, cuatro días en la feria son otra cosa."}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Y quien compra en Asia lo tiene peor: la Canton Fair cae a finales de octubre, justo cuando deberías estar preparando el Buen Fin."}]'::jsonb where nombre='Rezagados L7 · Comprar a ciegas' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/miercoles.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 8 de 10", "titulo": "La merma que sale de adentro"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tema incómodo pero necesario. 🔒"}, {"id": "t2", "tipo": "texto", "texto": "Cuando falta mercancía, la conversación va casi siempre al mismo lugar: el cliente."}, {"id": "t3", "tipo": "texto", "texto": "Los datos dicen otra cosa."}, {"id": "m1", "tipo": "metricas", "items": [{"cifra": "42.6%", "texto": "de la merma en LatAm es robo interno"}, {"cifra": "1.68%", "texto": "merma sobre ventas en México"}, {"cifra": "1.80%", "texto": "en tiendas de ropa"}]}, {"id": "t4", "tipo": "texto", "texto": "En Europa y Asia domina el robo del cliente. **En Latinoamérica, no.** Y México registró la tasa de merma más alta del estudio."}, {"id": "i1", "alt": "Dos empleados haciendo conteo físico de inventario", "pie": "El conteo no es desconfianza. Es la única forma de saber.", "src": "https://www.sacscloud.com/email/rezagados/rez-almacen-conteo.jpg", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "Esto no se resuelve con cámaras ni con sospechas. Se resuelve con **trazabilidad**: que cada movimiento tenga nombre y hora — quién recibió, quién traspasó, quién ajustó, quién dio el descuento. Cuando todo deja rastro, el problema casi siempre se acaba solo."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Los tres puntos ciegos de siempre"}, {"id": "l1", "tipo": "lista", "items": ["📦 **La recepción de mercancía.** Si nadie cuenta contra la factura, la diferencia nunca aparece.", "🔁 **El traspaso entre tiendas.** Sale de una y no llega a la otra: en el total de la cadena no se nota.", "🏷️ **El ajuste manual de inventario.** Si cualquiera puede corregir la existencia sin dejar razón, ahí se esconde todo."]}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. La referencia pública: Liverpool reportó 0.86% de merma sobre ventas de mercancía en 2025. Si tu número está muy arriba de eso, no es mala suerte."}]'::jsonb where nombre='Rezagados L8 · La merma que sale de adentro' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/atelier.jpg", "alt": "", "etiqueta": "Los lunes · Números de tu tienda · 9 de 10", "titulo": "El dueño es el sistema"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, la pregunta de hoy es incómoda y vale la pena. 🧭"}, {"id": "t2", "tipo": "texto", "texto": "**Si te fueras dos semanas sin señal, ¿qué se detiene?**"}, {"id": "t3", "tipo": "texto", "texto": "En casi todas las marcas de moda que crecen, la respuesta es la misma: la compra."}, {"id": "i1", "alt": "Encargada y equipo en junta antes de abrir la tienda", "pie": "Lo que solo vive en una cabeza no se puede delegar.", "src": "https://www.sacscloud.com/email/rezagados/rez-equipo.jpg", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "Nadie más sabe qué pedir, en qué cantidades ni a qué proveedor exigirle. No porque el equipo no pueda: porque **esa información no está escrita en ningún lado**. Vive en tu cabeza."}, {"id": "a1", "tipo": "aviso", "texto": "Y ahí está el techo real del crecimiento. No es el capital ni el local: es que la decisión más importante del negocio depende de una sola persona que no puede enfermarse, ni tomar vacaciones, ni abrir la cuarta tienda."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que cambia cuando se saca de la cabeza"}, {"id": "l1", "tipo": "lista", "items": ["📐 **La curva objetivo por categoría** deja de ser criterio y se vuelve regla escrita.", "🔢 **El mínimo por talla y tienda** lo puede revisar cualquiera.", "📋 **La sugerencia de compra** llega armada y tú apruebas, en vez de construirla desde cero."]}, {"id": "t5", "tipo": "texto", "texto": "No es quitarte la decisión. Es que la decisión llegue hecha para que tú solo digas sí o no."}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. La prueba: pídele a alguien de tu equipo que arme la próxima orden de compra sin ti. Lo que te pregunte es exactamente lo que falta escribir."}]'::jsonb where nombre='Rezagados L9 · El dueño es el sistema' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/almacen-conteo.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 1 de 10", "titulo": "El ejercicio de los 20 minutos"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, hoy algo que puedes hacer esta misma semana. ⏱️"}, {"id": "t2", "tipo": "texto", "texto": "No necesitas sistema ni reporte. Un riel, una libreta y veinte minutos."}, {"id": "i1", "alt": "Riel de ropa ordenado por talla con dos huecos visibles a la mitad de la corrida", "pie": "Los huecos de en medio son los que cuestan. Los de las puntas casi nunca.", "src": "https://www.sacscloud.com/email/rezagados/rez-miercoles.jpg", "tipo": "imagen"}, {"id": "s0", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "El ejercicio"}, {"id": "l1", "tipo": "lista", "items": ["1️⃣ **Elige tus cinco estilos que más venden.** Los que sabes de memoria.", "2️⃣ **Ordena cada uno por talla en el riel**, de la más chica a la más grande.", "3️⃣ **Anota los huecos**, pero solo los de EN MEDIO. Que falte la XS o la XXL es normal; que falte la M o la L en un estilo que sí rota es otra cosa.", "4️⃣ **Multiplica** los huecos de en medio por el precio de venta."]}, {"id": "t3", "tipo": "texto", "texto": "Ese número es lo que ese riel **no puede vender esta semana**, aunque tenga piezas colgadas."}, {"id": "a1", "tipo": "aviso", "texto": "Casi siempre sorprende, y por una razón: en el sistema esos estilos aparecen **con existencia**. Tienes piezas. Lo que no tienes es producto — a eso en el ramo se le llama estar **descabalado**, y es la palabra que más duele del negocio."}, {"id": "s1", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Si lo haces y el número te incomoda, escríbeme y te digo qué harían con eso las marcas que ya lo resolvieron. Sin agendar nada."}, {"id": "b1", "sub": "Mándame lo que te salió y lo vemos.", "href": "https://wa.me/525593027234?text=Hola,%20hice%20el%20ejercicio%20de%20los%2020%20minutos%20y%20quiero%20platicarlo", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "bag", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tienes más de una tienda, hazlo en las dos y compara. Ahí es donde casi siempre aparece la pieza que falta aquí y sobra allá."}]'::jsonb where nombre='Rezagados M1 · El ejercicio de los 20 minutos' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/pos.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 10 de 10", "titulo": "Llama a tres"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, este tip da miedo y por eso casi nadie lo hace. 📞"}, {"id": "t2", "tipo": "texto", "texto": "Saca tres clientas que compraban seguido y llevan más de seis meses sin volver."}, {"id": "t3", "tipo": "texto", "texto": "Llámales. **No para venderles nada.**"}, {"id": "i1", "alt": "Vendedora atendiendo en el mostrador de una boutique", "pie": "La respuesta que buscas no está en ningún reporte.", "src": "https://www.sacscloud.com/email/rezagados/rez-caja.jpg", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "La frase es literalmente esta: *«Hola, soy de la tienda. Vi que hace tiempo que no nos visitas y quería preguntarte si pasó algo o simplemente cambió tu ritmo.»*"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Las respuestas que vas a escuchar"}, {"id": "l1", "tipo": "lista", "items": ["😐 **«Nada, es que ando corriendo»** — la más común. Significa que no eres prioridad, y eso se arregla con contacto, no con descuento.", "📏 **«Ya no encuentro mi talla»** — la que más duele y la que más rápido se arregla.", "🎨 **«Ya no es tanto mi estilo»** — tu surtido se movió y ella no. Ojo si se repite.", "😶 **Silencio incómodo** — casi siempre hubo un mal servicio que nadie te contó."]}, {"id": "a1", "tipo": "aviso", "texto": "Tres llamadas de cinco minutos te van a dar más claridad sobre tu marca que cualquier reporte de ventas. Y lo mejor: **la mitad de las veces vuelven**, solo porque alguien se acordó de ellas."}, {"id": "s1", "tipo": "separador"}, {"id": "b1", "sub": "Cuéntanos qué te dijeron", "href": "https://wa.me/525593027234?text=Hola,%20llame%20a%20tres%20clientas%20que%20no%20volvian%20y%20quiero%20contarles", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Hazlas tú, no las delegues. Que llame la dueña cambia por completo cómo se recibe la llamada — y lo que te contestan."}]'::jsonb where nombre='Rezagados M10 · Llama a tres' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/rebajas.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 2 de 10", "titulo": "Los tres montones"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tip de miércoles. Este se hace con una hoja de cálculo y café. ☕"}, {"id": "t2", "tipo": "texto", "texto": "Saca la lista de tus estilos con dos columnas: **cuántas piezas tienes** y **cuántas vendiste la semana pasada**."}, {"id": "t3", "tipo": "texto", "texto": "Divide la primera entre la segunda. Ese número son las semanas que te dura."}, {"id": "i1", "alt": "Dos empleados haciendo conteo físico en el almacén de una tienda de moda", "pie": "Veinte minutos de conteo valen más que un mes de intuición.", "src": "https://www.sacscloud.com/email/rezagados/rez-almacen-conteo.jpg", "tipo": "imagen"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Ahora los tres montones"}, {"id": "l1", "tipo": "lista", "items": ["🔴 **Menos de 4 semanas** → PEDIR. Se te acaba antes de que llegue la reposición.", "🟢 **Entre 4 y 20** → DEJAR EN PAZ. Está haciendo su trabajo.", "🟠 **Más de 20 semanas** → MOVER. Ese es capital dormido, no un estilo que «todavía puede salir»."]}, {"id": "t4", "tipo": "texto", "texto": "Con esos tres montones ya tienes tu orden de compra y tu lista de rebajas. En veinte minutos."}, {"id": "a1", "tipo": "aviso", "texto": "El montón naranja es el que duele, y por eso casi nadie lo hace. Es el que compraste con ilusión. Pero cada semana que se queda ahí te cuesta el espacio y el dinero de lo que sí rota."}, {"id": "s1", "tipo": "separador"}, {"id": "b1", "sub": "Mándanos lo que te salió y lo revisamos", "href": "https://wa.me/525593027234?text=Hola,%20hice%20los%20tres%20montones%20y%20quiero%20platicar%20lo%20que%20salio", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tienes más de una tienda, hazlo por tienda. Un estilo puede estar rojo en una y naranja en otra: ahí no se compra, se traspasa."}]'::jsonb where nombre='Rezagados M2 · Los tres montones' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/equipo.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 3 de 10", "titulo": "Los cinco de siempre"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, este tip toma diez minutos y cambia cómo ves tu base. 👥"}, {"id": "t2", "tipo": "texto", "texto": "Saca a tus **veinte clientes que más han comprado** en los últimos doce meses. Solo el nombre y el total."}, {"id": "t3", "tipo": "texto", "texto": "Ahora suma cuánto pesan esos veinte sobre tu venta del año."}, {"id": "i1", "alt": "Momento de cobro en una boutique: una vendedora dobla una prenda en una bolsa de papel", "pie": "La clienta que vuelve cuesta una fracción de la que llega por primera vez.", "src": "https://www.sacscloud.com/email/rezagados/rez-caja.jpg", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "En casi todas las marcas de moda ese número está entre el **15 y el 30 por ciento**. Veinte personas."}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Y ahora la pregunta incómoda"}, {"id": "t5", "tipo": "texto", "texto": "¿Cuándo fue la última vez que alguien les escribió por algo que no fuera una promoción masiva?"}, {"id": "t6", "tipo": "texto", "texto": "No hablo de campañas. Hablo de: *«llegó algo que te va a gustar, te lo aparto»*."}, {"id": "a1", "tipo": "aviso", "texto": "Ahí está la oportunidad más barata que tiene una marca de moda: no cuesta pauta, no cuesta descuento, y la clienta ya te conoce. Solo hace falta **saber quiénes son y qué compraron**."}, {"id": "s2", "tipo": "separador"}, {"id": "t7", "tipo": "texto", "texto": "Si quieres que veamos cómo tener esa lista siempre a la mano y usarla sin que se sienta spam, agenda media hora."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. El ejercicio completo es sacar los veinte y ponerles al lado la fecha de su última compra. Si hay alguien de tus mejores clientes con seis meses sin volver, esa es tu llamada de mañana."}]'::jsonb where nombre='Rezagados M3 · Los cinco de siempre' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/mostrador.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 4 de 10", "titulo": "La foto de tu vitrina"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tip de esta semana, y es de los que se disfrutan. 📸"}, {"id": "t2", "tipo": "texto", "texto": "Todos los lunes, antes de abrir, tómale una foto a tu vitrina desde la banqueta. Siempre desde el mismo lugar."}, {"id": "i1", "alt": "Un visual merchandiser ajustando el vestido de un maniquí dentro del aparador al anochecer", "pie": "Desde adentro se ve el trabajo. Desde la banqueta se ve lo que ve tu clienta.", "src": "https://www.sacscloud.com/email/rezagados/rez-vitrina-noche.jpg", "tipo": "imagen"}, {"id": "t3", "tipo": "texto", "texto": "Al cabo de ocho semanas ponlas juntas en el teléfono y míralas en fila."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que vas a ver"}, {"id": "l1", "tipo": "lista", "items": ["🎨 **Si tu vitrina cambia de verdad** o solo se mueven las mismas piezas de lugar.", "⏱️ **Cuánto tiempo lleva ahí la misma prenda.** Casi siempre es más del que crees.", "🌈 **Si tu marca tiene un color** o cambia de personalidad cada mes.", "👗 **Si lo que está en la vitrina es lo que quieres vender** o lo que sobró."]}, {"id": "a1", "tipo": "aviso", "texto": "El sesgo que rompe: cuando estás adentro todos los días, la vitrina te parece nueva porque tú la moviste. La secuencia de fotos no tiene memoria ni cariño, y por eso te enseña lo que tu clienta ve al pasar por décima vez."}, {"id": "s1", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Y el cruce que lo vuelve serio: la prenda que lleva cinco semanas en la vitrina, ¿cuántas vendió en ese tiempo? Si la respuesta es «casi ninguna», tu mejor metro cuadrado está ocupado."}, {"id": "b1", "sub": "Cuéntanos qué encontraste", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20platicar%20sobre%20lo%20que%20veo%20en%20mi%20vitrina", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Hazlo también con la mesa de entrada. Es el segundo espacio que más vende y el que menos se revisa."}]'::jsonb where nombre='Rezagados M4 · La foto de tu vitrina' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/lunes.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 5 de 10", "titulo": "El recorrido de cinco minutos"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tip corto y físico. Se hace hoy mismo. 🚶‍♀️"}, {"id": "t2", "tipo": "texto", "texto": "Sal de tu tienda, cuenta hasta diez en la banqueta, y vuelve a entrar **como si fuera la primera vez**."}, {"id": "t3", "tipo": "texto", "texto": "Camina el recorrido completo sin arreglar nada. Solo mira."}, {"id": "i1", "alt": "Encargada y dos vendedoras en una junta corta antes de abrir la tienda", "pie": "Cinco minutos antes de abrir valen más que una junta de una hora.", "src": "https://www.sacscloud.com/email/rezagados/rez-equipo.jpg", "tipo": "imagen"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Las tres cosas que siempre aparecen"}, {"id": "l1", "tipo": "lista", "items": ["🏷️ **Una prenda sin precio.** Siempre hay una. Y la gente no pregunta: se va.", "🕳️ **Un hueco.** Un espacio en un riel donde había algo y ya no. Se lee como «aquí ya no queda nada bueno».", "🚪 **Un punto muerto.** Un rincón por donde nadie pasa, y casi siempre tiene mercancía."]}, {"id": "t4", "tipo": "texto", "texto": "Ninguna de las tres sale en un reporte. Las tres cuestan venta hoy."}, {"id": "a1", "tipo": "aviso", "texto": "Hazlo con alguien de tu equipo y que cada quien anote por separado. Van a coincidir en dos cosas y a discrepar en una — y esa tercera suele ser la más interesante, porque significa que uno de los dos ya se acostumbró."}, {"id": "s1", "tipo": "separador"}, {"id": "b1", "sub": "Cuéntanos qué te encontraste", "href": "https://wa.me/525593027234?text=Hola,%20hice%20el%20recorrido%20y%20quiero%20platicar%20lo%20que%20encontre", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Repítelo un sábado a las seis de la tarde, con la tienda llena. Es otra tienda distinta y casi nadie la ve, porque a esa hora todos están cobrando."}]'::jsonb where nombre='Rezagados M5 · El recorrido de cinco minutos' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-espejo.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 6 de 10", "titulo": "Pregúntale a quien se fue"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, este tip no cuesta nada y da la información más difícil de conseguir. 🗣️"}, {"id": "t2", "tipo": "texto", "texto": "Durante una semana, pídele a tu equipo que anote **una sola cosa**: cuando alguien se va sin comprar, ¿por qué?"}, {"id": "t3", "tipo": "texto", "texto": "Una palabra basta. En una libreta junto a la caja."}, {"id": "i1", "alt": "Una clienta saliendo del probador con dos prendas en la mano, decidiendo", "pie": "Lo que pasa aquí no aparece en ningún reporte de ventas.", "src": "https://www.sacscloud.com/email/rezagados/rez-probador.jpg", "tipo": "imagen"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Las respuestas casi siempre se repiten"}, {"id": "l1", "tipo": "lista", "items": ["📏 **«No estaba su talla»** — la más común, y la única que sí puedes resolver esta semana.", "🎨 **«No en ese color»** — te dice qué comprar la próxima vez.", "💵 **«Lo va a pensar»** — a veces es precio y a veces es que no encontró con qué combinarlo.", "🤷 **«Solo estaba viendo»** — pero si es la mayoría, el problema es el tráfico, no el surtido."]}, {"id": "a1", "tipo": "aviso", "texto": "Por qué importa tanto: **una venta que no ocurrió no se registra en ningún lado**. Tu sistema te dice perfectamente qué vendiste, y absolutamente nada de lo que estuviste a punto de vender. Esa libreta es el único lugar donde existe esa información."}, {"id": "s1", "tipo": "separador"}, {"id": "t5", "tipo": "texto", "texto": "Si la respuesta que más se repite es la talla, escríbenos: eso tiene solución concreta y rápida."}, {"id": "b1", "sub": "Mándanos lo que anotaron y lo vemos", "href": "https://wa.me/525593027234?text=Hola,%20hicimos%20la%20libreta%20de%20por%20que%20no%20compraron%20y%20quiero%20platicarlo", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Una semana basta. Más de dos y el equipo deja de anotar, así que mejor hacerlo corto, mirar el resultado y repetirlo en tres meses."}]'::jsonb where nombre='Rezagados M6 · Pregúntale a quien se fue' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/rack-color.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 7 de 10", "titulo": "Cuenta un solo estilo"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tip de miércoles, de los que sorprenden. 🔍"}, {"id": "t2", "tipo": "texto", "texto": "Elige **el estilo más caro** de tu tienda. Uno solo."}, {"id": "t3", "tipo": "texto", "texto": "Cuéntalo físicamente, talla por talla, color por color. Anótalo en papel."}, {"id": "t4", "tipo": "texto", "texto": "Ahora compáralo con lo que dice tu sistema."}, {"id": "i1", "alt": "Empleados contando inventario con lector y tableta", "pie": "Un estilo, diez minutos. Y casi siempre hay diferencia.", "src": "https://www.sacscloud.com/email/rezagados/rez-almacen-conteo.jpg", "tipo": "imagen"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Si no cuadra, está en uno de tres lugares"}, {"id": "l1", "tipo": "lista", "items": ["📦 **La recepción.** Llegaron menos de los que dice la factura y nadie lo revisó.", "🔁 **El traspaso.** Salió de otra tienda y no se registró la entrada aquí.", "🛒 **La venta.** Se cobró como otro producto, casi siempre por prisa en hora pico."]}, {"id": "a1", "tipo": "aviso", "texto": "Con un solo estilo caro no arreglas tu inventario, pero **sabes si tienes un problema y de qué tipo es**. Y eso decide si hace falta un conteo completo o solo apretar un proceso."}, {"id": "s1", "tipo": "separador"}, {"id": "b1", "sub": "¿No te cuadró? Escríbenos y lo revisamos contigo", "href": "https://wa.me/525593027234?text=Hola,%20conte%20un%20estilo%20y%20no%20me%20cuadra%20con%20el%20sistema", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Hazlo con el más caro a propósito: ahí una sola pieza de diferencia ya es dinero, y es donde más rápido se justifica arreglar el proceso."}]'::jsonb where nombre='Rezagados M7 · Cuenta un solo estilo' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/botas.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 8 de 10", "titulo": "La talla que pidieron"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, este tip cuesta cero y da información que ningún reporte tiene. 📝"}, {"id": "t2", "tipo": "texto", "texto": "Durante una semana, cada vez que alguien pida una talla que no hay, tu equipo anota tres cosas: **estilo, talla y si se la llevó de otro color o se fue**."}, {"id": "i1", "alt": "Clienta saliendo del probador decidiendo entre dos prendas", "pie": "La venta que no ocurrió no se registra en ningún lado. Esta libreta es el único lugar donde existe.", "src": "https://www.sacscloud.com/email/rezagados/rez-probador.jpg", "tipo": "imagen"}, {"id": "t3", "tipo": "texto", "texto": "Al final de la semana vas a tener dos cosas:"}, {"id": "l1", "tipo": "lista", "items": ["🛒 **Tu lista de compras real** — no la del histórico, sino la de la demanda que no pudiste atender.", "💸 **El costo de tus huecos** — multiplica cada «se fue» por tu ticket promedio."]}, {"id": "a1", "tipo": "aviso", "texto": "Y aquí está lo importante: esa demanda **no aparece en tu sistema de ventas**. Un producto que no se vendió porque no había se registra exactamente igual que uno que nadie quiso. Con los meses, tu histórico te enseña a comprar cada vez menos de lo que más te piden."}, {"id": "s1", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Si la misma talla se repite varias veces, ahí está tu decisión de compra de la próxima temporada — con evidencia, no con corazonada."}, {"id": "b1", "sub": "Mándanos tu lista y la leemos contigo", "href": "https://wa.me/525593027234?text=Hola,%20hice%20la%20lista%20de%20tallas%20que%20me%20pidieron%20y%20no%20tenia", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si tienes más de una tienda, anota también si la talla estaba en otra sucursal. Casi siempre sí — y esa venta se pudo salvar el mismo día."}]'::jsonb where nombre='Rezagados M8 · La talla que pidieron' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/miercoles.jpg", "alt": "", "etiqueta": "Los miércoles · Un ejercicio de diez minutos · 9 de 10", "titulo": "Reordena un riel por color"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, tip visual y rápido. Se hace hoy y se nota hoy. 🎨"}, {"id": "t2", "tipo": "texto", "texto": "Elige el riel que más se ve desde la entrada. Reordénalo **por color**, del más claro al más oscuro, en degradado."}, {"id": "t3", "tipo": "texto", "texto": "Ahora sal a la banqueta y mira tu tienda desde afuera."}, {"id": "i1", "alt": "Vendedora acomodando un riel en degradado de color", "pie": "El mismo inventario. Otra tienda.", "src": "https://www.sacscloud.com/email/moda/moda-rack-color.jpg", "tipo": "imagen"}, {"id": "t4", "tipo": "texto", "texto": "Es el mismo inventario. Pero desde la puerta se lee como una colección pensada, no como mercancía apilada."}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Por qué funciona"}, {"id": "l1", "tipo": "lista", "items": ["👁️ **El ojo entiende el degradado antes de leer nada.** Da sensación de abundancia y de orden al mismo tiempo.", "🕳️ **Los huecos se vuelven invisibles** cuando hay ritmo de color, y evidentes cuando no lo hay.", "👗 **La clienta encuentra su color** sin revisar prenda por prenda."]}, {"id": "a1", "tipo": "aviso", "texto": "Y el efecto secundario que casi nadie espera: **tú también vas a ver tu surtido distinto**. Cuando está por color se nota de inmediato si compraste ocho variantes de lo mismo o si te falta toda una familia."}, {"id": "s1", "tipo": "separador"}, {"id": "b1", "sub": "Mándanos la foto de cómo quedó", "href": "https://wa.me/525593027234?text=Hola,%20reordene%20un%20riel%20por%20color%20y%20quiero%20contarles%20como%20quedo", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Si vendes básicos y moda juntos, prueba separarlos antes de ordenar por color. Mezclados se pelean; separados, cada uno se vende mejor."}]'::jsonb where nombre='Rezagados M9 · Reordena un riel por color' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/mostrador.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 1 de 10", "titulo": "Cinco formas de comprar"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, es viernes, así que te enseño algo nuevo del sistema. ✨"}, {"id": "t2", "tipo": "texto", "texto": "Y este cambia cómo se compra una temporada."}, {"id": "s0", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "El problema que resuelve"}, {"id": "t3", "tipo": "texto", "texto": "La M se agotó el día 9. Los otros cincuenta y un días vendió cero — porque no había qué vender."}, {"id": "t4", "tipo": "texto", "texto": "Tu reporte dice que vendió 3 piezas. Igual que la XXL, que estuvo colgada dos meses."}, {"id": "t5", "tipo": "texto", "texto": "**Parecen el mismo dato. Son lo contrario.** Y con ese hueco adentro compras la siguiente corrida."}, {"id": "s1", "tipo": "separador"}, {"id": "h2", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "t6", "tipo": "texto", "texto": "Detecta que la talla estuvo agotada, estima lo que **habría** vendido, y te deja elegir con qué criterio. Mira cómo cambia la compra del mismo estilo:"}, {"id": "i2", "alt": "Animación: la misma venta con cuatro métodos distintos de compra y su total cambiando", "pie": "El mismo estilo. Entre el método más generoso y el más conservador, 13 piezas de diferencia.", "src": "https://www.sacscloud.com/email/rezagados/rez-viernes.gif", "tipo": "imagen"}, {"id": "l1", "tipo": "lista", "items": ["⚖️ **Promedio de tallas hermanas** — el recomendado para empezar.", "🔢 **Mínimo fijo por talla** — tú defines cuántas.", "📈 **Histórico de esa talla** — si antes vendía y ahora no había.", "📐 **Plantilla de curva por categoría** — tu curva objetivo, S:1 M:3 L:3 XL:2.", "🚫 **No estimar** — solo marca el hueco y decides tú."]}, {"id": "a1", "tipo": "aviso", "texto": "El detalle que más nos gusta: si esa categoría no tiene curva definida, el cuarto método **cae solo al promedio** en vez de tronar. Eso no se le ocurre a quien no ha vivido una temporada de compras."}, {"id": "i3", "alt": "Módulo de órdenes de compra de Sacs con la sugerencia por talla", "pie": "Órdenes de compra ▸ Nueva orden. Ahí vive.", "src": "https://www.sacscloud.com/email/trial/trial-compra.jpg", "tipo": "imagen"}, {"id": "s2", "tipo": "separador"}, {"id": "t7", "tipo": "texto", "texto": "¿Quieres verlo con un estilo tuyo? Mándame el que se te haya descabalado más rápido esta temporada y te enseño cuánto cambia la orden con cada método."}, {"id": "b1", "sub": "Con tus números, no con un ejemplo.", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20ver%20los%20metodos%20de%20compra%20con%20un%20estilo%20mio", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "bag", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Esto ya está vivo en todas las cuentas. Si tienes Sacs abierto, está en Inventarios ▸ Órdenes de compra."}]'::jsonb where nombre='Rezagados V1 · Cinco formas de comprar' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/cedis.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 10 de 10", "titulo": "Los reportes que solo existen en moda"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}! Cerramos la semana con lo menos vistoso y más útil. 📊"}, {"id": "t2", "tipo": "texto", "texto": "Un sistema genérico te da ventas por producto, por día y por vendedor. Está bien. **Pero ninguna de esas tres preguntas es la que te quita el sueño.**"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que sí preguntas"}, {"id": "l1", "tipo": "lista", "items": ["📐 **Curva de tallas real vs. la comprada** — por tienda, no promedio nacional.", "📈 **Sell-through por estilo y semana de vida** — el reloj que decide el rebaje.", "📦 **Semanas de cobertura** — cuánto te dura lo que tienes al ritmo actual.", "🕳️ **Quiebres de talla** — qué estilos ya no tienen su talla central.", "🔁 **Traspaso sugerido** — qué mover entre tiendas antes de comprar.", "🏷️ **Marcaje y margen después del descuento** — no el de lista.", "↩️ **Devoluciones por talla** — dónde tu tabla miente.", "🎨 **Ventas por color y por temporada.**", "👤 **Recompra por clienta** — quién volvió y en cuánto tiempo.", "💤 **Inventario sin movimiento** por días en piso."]}, {"id": "i1", "alt": "Pantalla de Sacs mostrando el análisis por tallas y sucursales", "pie": "Pantalla real de Sacs. No es una maqueta.", "src": "https://www.sacscloud.com/email/trial/trial-nivelacion.jpg", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "Ninguno de estos se puede armar «con un Excel encima» del sistema, porque **el sistema genérico ni siquiera guarda la talla como un dato**: la guarda como parte del nombre del producto. Ahí se acaba la conversación."}, {"id": "s1", "tipo": "separador"}, {"id": "t3", "tipo": "texto", "texto": "Si algo de esta lista es lo que te está costando trabajo hoy, esa es exactamente la conversación que vale la pena tener."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. El que más impacta al principio no es la curva: es **semanas de cobertura**. Es el que evita comprar lo que ya tienes."}]'::jsonb where nombre='Rezagados V10 · Los reportes que solo existen en moda' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/probador.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 2 de 10", "titulo": "Fotografía con IA"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, viernes de función nueva. Y esta ataca uno de los gastos que más duele en moda. 📸"}, {"id": "s0", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "El problema que nadie resuelve"}, {"id": "t2", "tipo": "texto", "texto": "Una sesión de fotos con modelo cuesta entre quince y cuarenta mil pesos, y hay que repetirla **cada temporada**."}, {"id": "t3", "tipo": "texto", "texto": "Así que casi todas las marcas terminan igual: la prenda colgada de un gancho, o tirada sobre una sábana con la luz que había."}, {"id": "t4", "tipo": "texto", "texto": "Y esa foto es la que va a la tienda en línea, al catálogo de WhatsApp y al marketplace. Es la primera impresión de tu marca."}, {"id": "s1", "tipo": "separador"}, {"id": "h2", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "t5", "tipo": "texto", "texto": "Cargas la foto que ya tienes. En minutos sale la prenda **puesta en un modelo**, con el fondo, la pose y el rostro que elijas."}, {"id": "i1", "alt": "Antes y después: la misma prenda fotografiada con celular sobre una sábana, y luego puesta en una modelo con calidad de catálogo", "pie": "Misma prenda. Misma foto de origen. La de la derecha no existió nunca.", "src": "https://www.sacscloud.com/email/rezagados/rez-viernes2.gif", "tipo": "imagen"}, {"id": "t6", "tipo": "texto", "texto": "No es un filtro ni una plantilla. Es tu prenda, con su color, su caída y sus botones."}, {"id": "l1", "tipo": "lista", "items": ["👗 **Personalizas rostro, pose y fondo** — para que se parezca a tu clienta, no a un banco de imágenes.", "⚡ **Minutos, no semanas.** Una colección completa en una tarde.", "💸 **Sin sesión, sin modelo, sin estudio.** Ni cuadrar agendas ni repetir cuando cambia la temporada.", "🎬 Y si quieres que se mueva, existe también en **video**."]}, {"id": "a1", "tipo": "aviso", "texto": "Dónde pega de verdad: los estilos que nunca fotografiaste porque no valía la pena pagar una sesión por ellos. Esos son los que hoy no venden en línea — no porque no gusten, sino porque nadie los ha visto bien."}, {"id": "s2", "tipo": "separador"}, {"id": "t7", "tipo": "texto", "texto": "Si quieres verlo con una prenda tuya, mándanos una foto por WhatsApp y te devolvemos el resultado. Sin compromiso: es la forma más rápida de saber si te sirve."}, {"id": "b1", "sub": "Mándanos una foto y te devolvemos el resultado", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20probar%20la%20fotografia%20con%20IA%20con%20una%20prenda%20mia", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "b2", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Se cotiza por sucursal y no viene en el plan base — es de los módulos que se agregan aparte. Pregunta y te paso el número exacto para tu caso."}]'::jsonb where nombre='Rezagados V2 · Fotografía con IA' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-espejo.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 3 de 10", "titulo": "Sugerencia de outfits"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, viernes de función nueva. Esta ataca el momento más caro de tu piso de venta. 👗"}, {"id": "t2", "tipo": "texto", "texto": "La clienta ya tiene la prenda en la mano. Le gusta. Y pregunta:"}, {"id": "t3", "tipo": "texto", "texto": "**«¿Con qué me lo pongo?»**"}, {"id": "t4", "tipo": "texto", "texto": "Ahí se decide si sale con una pieza o con tres. Y hoy esa respuesta depende de si le tocó la vendedora que lleva tres años o la que entró el mes pasado."}, {"id": "i1", "alt": "Una clienta saliendo del probador con dos prendas, decidiendo", "pie": "El momento exacto donde el ticket se duplica o no.", "src": "https://www.sacscloud.com/email/rezagados/rez-probador.jpg", "tipo": "imagen"}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "t5", "tipo": "texto", "texto": "La IA analiza tu historial de compras y las combinaciones que de verdad se han vendido juntas, y **sugiere el outfit completo** — sobre tu inventario real, no sobre un catálogo genérico."}, {"id": "l1", "tipo": "lista", "items": ["🧠 **Aprende de tus ventas**, no de tendencias de otro país.", "✅ **Solo sugiere lo que hay**, con su talla, en esa tienda.", "👩‍💼 **Iguala al equipo**: la vendedora nueva propone como la que lleva años."]}, {"id": "m1", "tipo": "metricas", "items": [{"cifra": "+40%", "texto": "en ticket promedio"}, {"cifra": "3 piezas", "texto": "en vez de una"}, {"cifra": "0", "texto": "capacitación extra"}]}, {"id": "a1", "tipo": "aviso", "texto": "Dónde pega más fuerte: en los estilos que no se venden solos pero funcionan como acompañamiento. Esos casi nunca se sugieren porque nadie se acuerda de ellos — y son justo los que llevan meses parados."}, {"id": "s2", "tipo": "separador"}, {"id": "t6", "tipo": "texto", "texto": "¿Lo vemos con tu catálogo? Se nota en la primera semana."}, {"id": "b1", "sub": "Te lo enseñamos con tus prendas", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20ver%20la%20sugerencia%20de%20outfits%20con%20mi%20catalogo", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "b2", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Se cotiza por sucursal y va aparte del plan base. Pregunta y te paso el número para tu caso."}]'::jsonb where nombre='Rezagados V3 · Sugerencia de outfits' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-vitrina.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 4 de 10", "titulo": "Pre-órdenes VIP"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, esta función cambia el orden de las cosas. Y el orden es donde está el dinero. 💎"}, {"id": "t2", "tipo": "texto", "texto": "Hoy compras la colección, llega, y **después** ves si gusta."}, {"id": "t3", "tipo": "texto", "texto": "Pagaste, guardaste y esperaste — con tu dinero adentro y sin saber."}, {"id": "s0", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "t4", "tipo": "texto", "texto": "Abres la colección **solo a tus clientas VIP** antes del lanzamiento. Ellas reservan con anticipo, y tú sabes qué se va a vender antes de que llegue el pedido."}, {"id": "i1", "alt": "Visual merchandiser preparando el aparador con un vestido azul cobalto al anochecer", "pie": "La colección se vende antes de estar en la vitrina.", "src": "https://www.sacscloud.com/email/rezagados/rez-vitrina-noche.jpg", "tipo": "imagen"}, {"id": "l1", "tipo": "lista", "items": ["🔒 **Acceso anticipado** para quien tú elijas. Se siente como un privilegio, porque lo es.", "💳 **Apartado con anticipo**, así que hay compromiso real y no una lista de deseos.", "🔔 **Notificación automática** cuando llega su pieza.", "📊 **Demanda antes de comprar**: sabes qué tallas y colores pedir de más y cuáles casi no."]}, {"id": "a1", "tipo": "aviso", "texto": "El efecto secundario es el mejor: tus clientas VIP dejan de ser una etiqueta en el sistema y se vuelven las primeras en ver todo. Eso construye la relación que ninguna promoción compra."}, {"id": "s1", "tipo": "separador"}, {"id": "t5", "tipo": "texto", "texto": "Si tienes una colección próxima, es el momento de montarlo — se arma en días, no en semanas."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "b2", "sub": "¿Tienes colección en puerta? Escríbenos", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20ver%20las%20pre-ordenes%20VIP%20para%20mi%20proxima%20coleccion", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Con veinte clientas VIP y una reserva promedio de dos piezas, ya financias parte del pedido antes de pagarlo. Esa es la cuenta que hace que valga la pena."}]'::jsonb where nombre='Rezagados V4 · Pre-órdenes VIP' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/wow-planta.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 5 de 10", "titulo": "Pasarelas en tienda"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, esta es de las que no esperas de un sistema de punto de venta. ✨"}, {"id": "t2", "tipo": "texto", "texto": "Un desfile en tu tienda es la forma más rápida de convertir una noche en la venta de una semana. Y de que tus clientas traigan a sus amigas."}, {"id": "t3", "tipo": "texto", "texto": "El problema nunca fue la idea. Fue la logística."}, {"id": "i1", "alt": "Backstage de un desfile en tienda: modelos en fila esperando junto a un burro de ropa", "pie": "Lo complicado nunca fue el desfile. Fue lo de atrás.", "src": "https://www.sacscloud.com/email/rezagados/rez-pasarela.jpg", "tipo": "imagen"}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "l1", "tipo": "lista", "items": ["👠 **Arma los outfits** con piezas de tu inventario real, con su talla y su existencia.", "📋 **Orden de salida** por modelo y por look, para que nadie improvise esa noche.", "🔖 **Reserva en el momento**: la clienta ve el look, lo aparta desde la pasarela y queda ligado a su ficha.", "📈 **Mide qué look vendió**, no solo cuánto se vendió en total."]}, {"id": "a1", "tipo": "aviso", "texto": "Ese último punto es el que casi nadie tiene. Después de un evento todos saben cuánto vendieron; muy pocos saben **qué look** fue el que movió la noche — que es exactamente lo que hay que repetir en la vitrina el lunes."}, {"id": "s2", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Si tienes espacio y clientas, esto se monta con lo que ya tienes. Te contamos cómo."}, {"id": "b1", "sub": "Te decimos qué necesitas", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20saber%20como%20montar%20una%20pasarela%20en%20mi%20tienda", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. No hace falta una tienda enorme. Los desfiles que mejor funcionan son los de treinta personas y ocho looks, en una tarde entre semana."}]'::jsonb where nombre='Rezagados V5 · Pasarelas en tienda' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/hoja-linea.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 6 de 10", "titulo": "Temporadas y colecciones"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}, esta función es menos vistosa que otras y probablemente la que más te ahorre. 🗂️"}, {"id": "t2", "tipo": "texto", "texto": "En moda no vendes productos: vendes **temporadas**. Y casi ningún sistema lo entiende."}, {"id": "t3", "tipo": "texto", "texto": "Por eso tu reporte mezcla la blusa de esta primavera con la del año pasado como si fueran lo mismo — y no lo son ni en precio, ni en margen, ni en urgencia."}, {"id": "i1", "alt": "Equipo de tienda montando el piso de rebajas con racks de ropa de colores", "pie": "Cuando el sistema no sabe de temporadas, tú tienes que acordarte de todo.", "src": "https://www.sacscloud.com/email/rezagados/rez-rebajas.jpg", "tipo": "imagen"}, {"id": "s1", "tipo": "separador"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Lo que ahora hace Sacs"}, {"id": "l1", "tipo": "lista", "items": ["📅 **Cada prenda pertenece a su temporada**, con fecha de entrada y de salida.", "🧮 **Sell-through por temporada**, no revuelto con el histórico.", "⏳ **Alerta de fin de temporada** antes de que sea saldo, no después.", "🔄 **Transición**: qué entra, qué se rebaja y qué se guarda para el año que viene."]}, {"id": "a1", "tipo": "aviso", "texto": "La diferencia práctica: dejas de decidir la rebaja por corazonada o por calendario del centro comercial, y empiezas a decidirla por **dónde va esa temporada contra la anterior**. Es la misma información, ordenada por donde de verdad se corta."}, {"id": "s2", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Si vas entrando a una transición de temporada, es el mejor momento para montarlo."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. El caso que más se repite: mercancía de hace dos temporadas que sigue contando como inventario a valor lleno. En papel eres más rico de lo que eres."}]'::jsonb where nombre='Rezagados V6 · Temporadas y colecciones' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/pasarela.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 7 de 10", "titulo": "Video automático con IA"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}! Viernes de novedad, y esta es de las que dan envidia. 🎬"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Video automático con IA"}, {"id": "t2", "tipo": "texto", "texto": "Tu catálogo ya tiene fotos de cada producto. **Ese es todo el insumo.**"}, {"id": "t3", "tipo": "texto", "texto": "Seleccionas los productos, eliges el formato — vertical para reels y TikTok, cuadrado para el feed — y Sacs arma el video: entradas, transiciones, precio en pantalla y el nombre de tu marca."}, {"id": "i1", "alt": "Animación de fotos de producto convirtiéndose en un video vertical", "pie": "De la ficha del producto al reel, sin diseñador.", "src": "https://www.sacscloud.com/email/rezagados/rez-viernes.gif", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "El cuello de botella de las redes de una boutique nunca es la idea: es **quién se sienta a editar**. Cuando el video sale del mismo catálogo que ya mantienes, publicar deja de depender de que alguien tenga la tarde libre."}, {"id": "s1", "tipo": "separador"}, {"id": "h1b", "tipo": "encabezado", "nivel": 2, "texto": "Lo que se puede armar en un rato"}, {"id": "l1", "tipo": "lista", "items": ["🆕 **Lo que llegó esta semana** — se filtra por fecha de recepción y sale solo.", "🔥 **Los más vendidos del mes** — el propio reporte elige los productos.", "🏷️ **Lo que está en rebaja** — con el precio tachado en pantalla.", "👗 **Una colección completa**, en el orden que tú definas."]}, {"id": "t4", "tipo": "texto", "texto": "Y como sale del catálogo, **el precio y las tallas del video son los de verdad**. No el de la lista que alguien pasó a Canva hace tres semanas."}, {"id": "s2", "tipo": "separador"}, {"id": "b1", "sub": "¿Quieres verlo con tus propios productos? Escríbenos", "href": "https://wa.me/525593027234?text=Hola,%20quiero%20ver%20el%20video%20automatico%20con%20IA", "tipo": "boton", "align": "center", "texto": "📲 Enviar WhatsApp"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. El que más se usa es el de «llegó nuevo». Publicar los ingresos el mismo día que entran a piso cambia por completo la primera semana de vida de un estilo."}]'::jsonb where nombre='Rezagados V7 · Video automático con IA' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/vitrina-noche.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 8 de 10", "titulo": "Renta de vestidos de gala"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}! Novedad de viernes para quien vende ocasión especial. 👗"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Renta de vestidos y trajes de gala"}, {"id": "t2", "tipo": "texto", "texto": "Un vestido de gala se vende una vez. **Rentado deja dinero seis, ocho, doce veces** — y el problema nunca fue la idea, fue llevar la cuenta."}, {"id": "t3", "tipo": "texto", "texto": "Ahora vive dentro de Sacs, con el mismo catálogo:"}, {"id": "l1", "tipo": "lista", "items": ["📅 **Calendario por prenda** — quién la tiene, qué días está apartada y cuándo regresa.", "💵 **Depósito en garantía** — se registra al salir y se devuelve al volver, con su movimiento en caja.", "🧵 **Estado a la devolución** — si vuelve con un daño, se cobra el ajuste y queda anotado en la ficha.", "🔁 **Rotación real** — cuántas veces se ha rentado cada pieza y cuánto lleva recuperado."]}, {"id": "i1", "alt": "Modista ajustando un vestido largo sobre maniquí en el taller", "pie": "La misma prenda, muchas veces. El taller es parte del negocio.", "src": "https://www.sacscloud.com/email/rezagados/rez-taller.jpg", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "La métrica que aparece y que nadie tenía: **cuánto lleva generado cada pieza contra lo que costó**. Con eso se decide qué se compra la próxima temporada y qué se saca a venta de liquidación cuando ya se pagó sola."}, {"id": "s1", "tipo": "separador"}, {"id": "t4", "tipo": "texto", "texto": "Y si vendes y rentas al mismo tiempo, es el mismo inventario: una prenda apartada para renta no aparece disponible para venta ese fin de semana."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. Funciona igual para trajes de novio, XV años y disfraces de temporada. Todo lo que sale y vuelve."}]'::jsonb where nombre='Rezagados V8 · Renta de vestidos de gala' and archived_at is null;
update email_templates set layout='lienzo', updated_at=now(), bloques='[{"id": "portada", "tipo": "portada", "imagen": "https://www.sacscloud.com/email/portadas/etiqueta.jpg", "alt": "", "etiqueta": "Los viernes · Lo que Sacs hace hoy · 9 de 10", "titulo": "De la tela a la etiqueta"}, {"id": "t1", "tipo": "texto", "texto": "{{nombre|Hola}}! Esta es para quien no solo compra: **produce**. 🧵"}, {"id": "h1", "tipo": "encabezado", "nivel": 2, "texto": "Módulo de fabricación"}, {"id": "t2", "tipo": "texto", "texto": "Si mandas maquilar, hoy tu costo por prenda es una estimación. La tela va en una libreta, el avío en otra, lo que le pagaste al taller en el WhatsApp del taller."}, {"id": "t3", "tipo": "texto", "texto": "El módulo cierra ese círculo:"}, {"id": "l1", "tipo": "lista", "items": ["🧶 **Insumos con existencia propia** — tela, avíos, etiquetas, bolsas. Se descuentan cuando entran a producción.", "🏭 **Órdenes al maquilero** — qué se le entregó, qué debe regresar y cuándo.", "📐 **Consumo por talla** — una talla grande lleva más tela, y el costo lo refleja.", "🏷️ **Costo real por prenda terminada** — insumos + mano de obra + lo que se mermó."]}, {"id": "i1", "alt": "Taller de confección con máquinas y prendas en proceso", "pie": "El costo de una prenda propia no es lo que te cobró el taller.", "src": "https://www.sacscloud.com/email/rezagados/rez-taller.jpg", "tipo": "imagen"}, {"id": "a1", "tipo": "aviso", "texto": "El número que cambia decisiones: **el costo real, con merma incluida**. Casi siempre está 12-18% arriba de lo que se traía en la cabeza — y con eso el margen de la marca propia deja de ser un supuesto."}, {"id": "s1", "tipo": "separador"}, {"id": "t5", "tipo": "texto", "texto": "Y cuando la prenda termina, entra al catálogo como cualquier otra: con sus tallas, sus colores y su costo ya calculado."}, {"id": "b1", "sub": "30 minutos, sin costo · eliges el horario y queda confirmada al momento", "href": "https://www.sacscloud.com/agendar/demo", "tipo": "boton", "align": "center", "texto": "📅 Agendar una demo"}, {"id": "fi", "tipo": "firma", "nombre": "Andrea Gutiérrez Araujo", "puesto": "Tu consultora en Sacs", "foto_url": "https://www.sacscloud.com/images/andrea-consultora.jpg"}, {"id": "pd", "tipo": "texto", "texto": "P.D. La sorpresa habitual está en los avíos. Nadie los cuenta y suelen ser la diferencia entre un margen sano y uno que no lo era."}]'::jsonb where nombre='Rezagados V9 · De la tela a la etiqueta' and archived_at is null;
commit;
